{
  "root": "main_stack",
  "state": {
    "chartData": [
      { "hoursStudied": 5, "examScore": 75 },
      { "hoursStudied": 8, "examScore": 88 },
      { "hoursStudied": 3, "examScore": 60 },
      { "hoursStudied": 10, "examScore": 95 },
      { "hoursStudied": 6, "examScore": 80 },
      { "hoursStudied": 7, "examScore": 85 },
      { "hoursStudied": 4, "examScore": 70 },
      { "hoursStudied": 9, "examScore": 92 },
      { "hoursStudied": 2, "examScore": 55 },
      { "hoursStudied": 11, "examScore": 98 }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_overview",
        "section_chart_title",
        "section_chart_description",
        "chart_card",
        "section_correlation_title",
        "section_correlation_description"
      ]
    },
    "title_overview": {
      "type": "Text",
      "props": {
        "text": "Student Performance Overview",
        "variant": "h1"
      },
      "children": []
    },
    "section_chart_title": {
      "type": "Text",
      "props": {
        "text": "Hours Studied vs. Exam Score Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "section_chart_description": {
      "type": "Text",
      "props": {
        "text": "This visualization depicts the relationship between the number of hours students spent studying and their corresponding exam scores.",
        "variant": "body"
      },
      "children": []
    },
    "chart_card": {
      "type": "Card",
      "props": {},
      "children": [
        "chart_main_table"
      ]
    },
    "chart_main_table": {
      "type": "Table",
      "props": {
        "title": "Student Study Hours vs. Exam Scores",
        "columns": [
          { "key": "hoursStudied", "label": "Hours Studied" },
          { "key": "examScore", "label": "Exam Score" }
        ],
        "statePath": "/chartData",
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "hoursStudied",
        "highlightColumns": ["examScore"]
      },
      "children": []
    },
    "section_correlation_title": {
      "type": "Text",
      "props": {
        "text": "Observed Correlation",
        "variant": "h2"
      },
      "children": []
    },
    "section_correlation_description": {
      "type": "Text",
      "props": {
        "text": "Based on the provided data points, there appears to be a strong positive correlation between hours studied and exam scores. As the number of hours students spent studying increases, their exam scores consistently tend to be higher. This suggests that more study time generally leads to better academic performance in this group of students.",
        "variant": "body"
      },
      "children": []
    }
  }
}
